<?php declare(strict_types=1);
$ct=$ivCatalogueText;
$filters=scalarFields($_GET,['q','member','location','state']);$summary=$inventory->summary();$catalogue=$inventory->whereaboutsPage($filters,$_GET['where_page']??1);$whereRoute=['view'=>'inventory','tab'=>'where']+$filters;
?>
<link rel="stylesheet" href="inventory-catalogue.css?v=2">
<div class="iv-stats iv-catalogue-stats"><?php foreach([['Gegenstände',$summary['items'],'items'],['Offene Ausleihen',$summary['reserved']+$summary['issued'],'loans&state=open'],['Überfällig',$summary['overdue'],'loans&state=overdue'],['Unter Mindestbestand',$summary['low'],'items&status=low']]as[$label,$number,$link]): ?><a class="card" href="?view=inventory&amp;tab=<?= e($link) ?>"><span><?= e($ct($label)) ?></span><strong><?= (int)$number ?></strong></a><?php endforeach ?></div>
<section class="card iv-catalogue" id="inventory-where-catalogue"><div class="section-heading"><h2><?= e($ct('Wo ist was?')) ?></h2><?php if($loanWrite): ?><a class="btn btn-solid theme-primary" href="?view=inventory&amp;tab=loans&amp;new_loan=1"><?= e($ct('+ Ausleihe')) ?></a><?php endif ?></div>
<form method="get" action="#inventory-where-catalogue" class="iv-filter" data-inventory-live-filter><?= hidden('view','inventory').hidden('tab','where') ?>
<?php ivField('q',$ct('Gegenstand suchen (Name, Nummer, Seriennummer)'),input($_GET,'q'));ivField('member',$ct('Mitglied / Verantwortung'),input($_GET,'member'),'select',\Kulturhus\Verein\Web\InventoryCatalogueForm::options(array_replace($personOptions,[''=>$ct('Alle Personen')]),input($_GET,'member'),$ct('Ausgewählte Person nicht verfügbar – Filter prüfen')));ivField('location',$ct('Lagerort'),input($_GET,'location'),'select',\Kulturhus\Verein\Web\InventoryCatalogueForm::options(array_replace($locationOptions,[''=>$ct('Alle Orte')]),input($_GET,'location'),$ct('Ausgewählter Lagerort nicht verfügbar – Filter prüfen')));ivField('state',$ct('Status'),input($_GET,'state'),'select',array_map($ct,[''=>'Alle','available'=>'Verfügbar','reserved'=>'Reserviert','issued'=>'Ausgeliehen','blocked'=>'Gesperrt / Wartung'])); ?>
<button class="btn btn-outline theme-secondary"><?= e($ct('Filtern')) ?></button></form><p role="status" aria-live="polite" data-inventory-filter-status></p>
<div data-inventory-filter-results><p data-inventory-where-summary><?= e($ct('{count} Teilbestände · Seite {page} von {pages}',['count'=>$catalogue['total'],'page'=>$catalogue['page'],'pages'=>$catalogue['pages']])) ?></p>
<div class="iv-catalogue-cards"><?php foreach($catalogue['rows']as$r): ?><article class="iv-catalogue-card" data-inventory-where="<?= e($r['item_id'].':'.$r['location_id'].':'.$r['state'].':'.$r['loan_id']) ?>">
<a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'inventory','tab'=>'items','item'=>$r['item_id'],'return_where'=>1,'where_page'=>$catalogue['page']]+$filters)) ?>"><?= e($r['item_name']) ?></a><p><?= e($r['code']) ?><?= $r['responsible_name']!==null&&$r['responsible_name']!==''?e($ct(' · Zuständig: {name}',['name'=>$r['responsible_name']])):'' ?></p>
<dl><div><dt><?= e($ct('Menge')) ?></dt><dd><?= e(\Kulturhus\Verein\Inventory::contentSummary($r,(int)$r['quantity'],$ct)?:$r['quantity'].' '.$r['unit']) ?></dd></div><div><dt><?= e($ct('Aktueller Ort')) ?></dt><dd><?= e($r['location_name']!==null&&$r['location_name']!==''?$r['location_name']:$ct('Standort nicht bestätigt')) ?></dd></div><div><dt><?= e($ct('Aufbewahrung')) ?></dt><dd><?= e(implode(' · ',array_filter([$r['building'],$r['room'],$r['location_shelf'],$r['holder_name']],static fn($v)=>$v!==null&&$v!==''))) ?></dd></div><div><dt><?= e($ct('Status')) ?></dt><dd><?= e($ct(['available'=>'Verfügbar','reserved'=>'Reserviert','blocked'=>'Gesperrt / Wartung','issued'=>'Ausgeliehen'][$r['state']])) ?></dd></div><div><dt><?= e($ct('Zuletzt bestätigt')) ?></dt><dd><?= $r['confirmed_at']?e((new DateTimeImmutable($r['confirmed_at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i')):e($ct('Noch nicht bestätigt')) ?> · <?= e($ivActorNames->label($r['confirmed_by']??null,$ct)) ?></dd></div></dl>
<?php if($r['loan_id']): ?><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'inventory','tab'=>'loans','loan'=>$r['loan_id'],'return_where'=>1,'where_page'=>$catalogue['page']]+$filters)) ?>"><?= e($ct('Rückgabe: {date} →',['date'=>dateDe($r['due_on'])])) ?></a><p><?= e($r['purpose']) ?></p><?php endif ?></article>
<?php endforeach;if(!$catalogue['rows']): ?><p><?= e($ct('Keine Bestände gefunden.')) ?></p><?php endif ?></div>
<nav class="iv-catalogue-pages" aria-label="<?= e($ct('Bestandsseiten')) ?>"><?php foreach([-1=>'Vorherige',1=>'Nächste']as$delta=>$label)if($catalogue['page']+$delta>=1&&$catalogue['page']+$delta<=$catalogue['pages']): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($whereRoute+['where_page'=>$catalogue['page']+$delta])) ?>#inventory-where-catalogue"><?= e($ct($label)) ?></a><?php endif ?></nav>
<form method="get" action="#inventory-where-catalogue" class="iv-catalogue-pages"><?php foreach($whereRoute as$key=>$value)echo hidden($key,$value); ?><label><?= e($ct('Seite')) ?><input class="form-control" type="number" name="where_page" min="1" max="<?= (int)$catalogue['pages'] ?>" value="<?= (int)$catalogue['page'] ?>" required></label><button class="btn btn-outline theme-secondary"><?= e($ct('Seite anzeigen')) ?></button></form>
</div></section><script src="inventory-where-filter.js?v=3" defer></script>
